// S2.3: Rapid Select / Enter Key Hammering (50 Keystrokes)
await test('S2', '3', 'Rapid Select / Enter Key Hammering (50 Keystrokes in 200ms)', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const sandbox = window.document.createElement('div');
  sandbox.id = 'test-spatial-sandbox';
  activeView.appendChild(sandbox);

  const targetBtn = window.document.createElement('button');
  targetBtn.id = 'target-select-btn';
  targetBtn.setAttribute('data-nav', 'true');
  targetBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 200, width: 80, height: 40 }));
  sandbox.appendChild(targetBtn);

  let clickCount = 0;
  targetBtn.addEventListener('click', () => { clickCount++; });

  nav.setFocus(targetBtn);

  for (let k = 0; k < 50; k++) {
    sendKey(window, 'Enter', 13);
  }

  assert.strictEqual(clickCount, 50, 'All 50 Enter actions must trigger click on focused element without focus loss');
  assert.strictEqual(nav.getCurrentFocus(), targetBtn, 'Focus must remain firmly on target button');
  const focusedList = window.document.querySelectorAll('.focused');
  assert.strictEqual(focusedList.length, 1, 'Exactly one element focused');
});

