node -e '
(async () => {
  const jsonRes = await fetch("http://localhost:33365/json");
  const targets = await jsonRes.json();
  const page = targets.find(t => t.type === "page" && t.url.includes("com.cinejoy.tv"));
  if (!page) {
    console.error("Target page not found!");
    process.exit(1);
  }

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  console.log("Connected to WAM DevTools via WebSocket!");

  let idCounter = 1;
  function call(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = idCounter++;
      const handler = (event) => {
        const msg = JSON.parse(event.data);
        if (msg.id === id) {
          ws.removeEventListener("message", handler);
          if (msg.error) reject(msg.error);
          else resolve(msg.result);
        }
      };
      ws.addEventListener("message", handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  const evalCode = `(() => {
    const header = document.getElementById("app-header");
    const shade = document.getElementById("shade");
    const bgBlur = document.getElementById("bgBlur");
    const bodyBg = window.getComputedStyle(document.body).backgroundColor;
    const bodyBgHex = window.getComputedStyle(document.body).getPropertyValue("--bg-cinema");
    const navPill = document.querySelector(".nav-glass-pill");
    const tabs = Array.from(document.querySelectorAll(".nav-pill-item")).map(t => ({
      text: t.textContent.trim(),
      tabId: t.dataset.tab,
      active: t.classList.contains("active")
    }));
    const hero = document.getElementById("hero");
    const heroSpotlight = document.querySelector(".hero-spotlight, .hero-content, .hero");
    const catalogCards = document.querySelectorAll(".card, .media-card");
    const appInfoVersion = window.appinfo ? window.appinfo.version : null;

    return {
      hasAppHeader: !!header,
      appHeaderTag: header ? header.tagName : null,
      appHeaderClass: header ? header.className : null,
      hasShade: !!shade,
      shadeClass: shade ? shade.className : null,
      hasBgBlur: !!bgBlur,
      bgBlurClass: bgBlur ? bgBlur.className : null,
      bodyBgColor: bodyBg,
      bodyBgCinemaVar: bodyBgHex,
      hasNavGlassPill: !!navPill,
      navTabs: tabs,
      hasHero: !!hero,
      heroClass: hero ? hero.className : null,
      catalogCardCount: catalogCards.length,
      currentView: document.querySelector(".view.active")?.id || "unknown",
      windowResolution: window.innerWidth + "x" + window.innerHeight
    };
  })()`;

  const evalRes = await call("Runtime.evaluate", { expression: evalCode, returnByValue: true });
  console.log("LIVE DOM VERIFICATION RESULT:\n", JSON.stringify(evalRes.result.value, null, 2));

  // Let us also capture a screenshot of the TV screen via Page.captureScreenshot if supported
  try {
    const screenshotRes = await call("Page.captureScreenshot", { format: "png" });
    if (screenshotRes && screenshotRes.data) {
      const fs = require("fs");
      const path = "/home/prem/webos-projects/cinejoy-webos/reports/tv-live-render-screenshot.png";
      fs.writeFileSync(path, Buffer.from(screenshotRes.data, "base64"));
      console.log("Screenshot successfully saved to: " + path);
    }
  } catch (err) {
    console.log("Page.captureScreenshot note:", err.message);
  }

  ws.close();
  process.exit(0);
})();
'

